'use strict';
function renderKazakhstan(){
 const f=DATA.kazakhstan_focus,host=$('#kazakhstan-focus');if(!f||!host)return;
 host.innerHTML=`<div class="league-section-intro"><span class="section-kicker">NUEVO DESTINO · VERIFICADO ${esc(f.checked)}</span><h3>Kazakhstan · un recorrido por separado para cada uno</h3><p>${esc(f.conclusion)}</p></div><div class="kazakhstan-dates" aria-label="las etapas de RGT anunciadas">${f.announced.map((a,i)=>`${i?'<span class="kazakhstan-arrow" aria-hidden="true">→</span>':''}<button data-open="${esc(a.id)}"><span>${esc(a.date)}</span><strong>${esc(a.city)}</strong><small>RGT · edad se aclara</small></button>`).join('')}</div><div class="kazakhstan-children">${f.children.map(c=>`<article class="camp-route"><h4>${esc(c.name)}</h4><p>${esc(c.detail)}</p><div class="camp-route-links">${c.event_ids.map(id=>{const e=EVENTS.find(x=>x.id===id);return e?`<button class="text-button" data-open="${esc(id)}">${esc(e.title)} ↗</button>`:''}).join('')}</div></article>`).join('')}</div><details class="kazakhstan-gates"><summary>idioma, permiso extranjero y nuevas estaciones</summary><ul>${f.gates.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><p>${esc(f.limitations)}</p></details><div class="kazakhstan-actions"><button class="button secondary" data-kazakhstan-catalog>todos los registros de Kazajstán</button><a class="league-link" href="downloads/STEM_Kazakhstan.md" download>descargar el resumen ↓</a></div>`;
}
document.addEventListener('click',event=>{if(!event.target.closest('[data-kazakhstan-catalog]'))return;reset();state.country='KAZ';state.excluded=true;setView('catalog');$('.workspace').scrollIntoView({behavior:'smooth',block:'start'});});
